/**
 * Patch the Next.js standalone HTTP server timeouts after boot.
 * Traefik/Cloudflare idle timeouts are typically 60s — keepAlive must be higher.
 *
 * Usage (docker CMD): node server-timeouts.mjs
 * Falls through to ./server.js generated by `next build` standalone output.
 */
import { createRequire } from "node:module";
import http from "node:http";
import https from "node:https";

const KEEP_ALIVE_MS = Math.max(1000, Number(process.env.HTTP_KEEP_ALIVE_MS) || 65_000);
const HEADERS_MS = Math.max(KEEP_ALIVE_MS + 1000, Number(process.env.HTTP_HEADERS_TIMEOUT_MS) || 70_000);

const origListen = http.Server.prototype.listen;
http.Server.prototype.listen = function patchedListen(...args) {
  try {
    this.keepAliveTimeout = KEEP_ALIVE_MS;
    this.headersTimeout = HEADERS_MS;
    this.requestTimeout = Math.max(HEADERS_MS, Number(process.env.HTTP_REQUEST_TIMEOUT_MS) || 120_000);
  } catch {
    /* ignore */
  }
  return origListen.apply(this, args);
};

const origHttpsListen = https.Server.prototype.listen;
https.Server.prototype.listen = function patchedHttpsListen(...args) {
  try {
    this.keepAliveTimeout = KEEP_ALIVE_MS;
    this.headersTimeout = HEADERS_MS;
  } catch {
    /* ignore */
  }
  return origHttpsListen.apply(this, args);
};

const require = createRequire(import.meta.url);
require("./server.js");
